import { createPortal } from 'react-dom';
import React, { useEffect, useMemo, useState } from 'react';
import { X, Scale, Search } from 'lucide-react';

// Shows THIRD_PARTY_NOTICES.txt (generated by scripts/generate-notices.mjs and
// bundled with the app): the copyright notices and licenses of everything the
// app includes.
export const LicensesModal: React.FC<{ isOpen: boolean; onClose: () => void }> = ({ isOpen, onClose }) => {
  const [text, setText] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);
  const [query, setQuery] = useState('');

  useEffect(() => {
    if (!isOpen || text !== null) return;
    fetch(`${import.meta.env.BASE_URL}THIRD_PARTY_NOTICES.txt`)
      .then(r => (r.ok ? r.text() : Promise.reject(new Error(String(r.status)))))
      .then(setText)
      .catch(() => setFailed(true));
  }, [isOpen, text]);

  // Filter to the entries that mention the search (an entry is a block between
  // the "-----" separator lines).
  const shown = useMemo(() => {
    if (!text) return '';
    const q = query.trim().toLowerCase();
    if (!q) return text;
    return text
      .split(/\n(?=[^\n]+\n-{78}\n)/)
      .filter(block => block.toLowerCase().includes(q))
      .join('\n');
  }, [text, query]);

  if (!isOpen) return null;

  return createPortal(
    <div className="fixed inset-0 z-[200] bg-black/80 backdrop-blur-md flex items-end sm:items-center justify-center">
      <div className="w-full max-w-2xl bg-app-surface border border-app-theme rounded-t-3xl sm:rounded-3xl h-[88vh] flex flex-col overflow-hidden shadow-2xl">
        <div className="flex items-center justify-between px-6 pt-6 pb-4 border-b border-app-theme">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-2xl bg-app-card border border-app-theme text-app-primary">
              <Scale className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-xl font-bold text-app-primary">Open-source licenses</h2>
              <p className="text-xs text-app-secondary">Code and libraries included in FRF Music</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 text-app-secondary rounded-full" title="Close">
            <X className="w-6 h-6" />
          </button>
        </div>
        <div className="px-6 py-3 border-b border-app-theme">
          <div className="relative">
            <Search className="absolute left-3 top-2.5 w-4 h-4 text-app-secondary" />
            <input
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Find a library"
              className="w-full bg-app-card border border-app-theme rounded-full py-2 pl-9 pr-3 text-sm text-app-primary placeholder:text-app-secondary outline-none"
            />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto px-6 py-4">
          {failed ? (
            <p className="text-sm text-app-secondary">The license list could not be opened.</p>
          ) : text === null ? (
            <p className="text-sm text-app-secondary">Loading...</p>
          ) : (
            <pre className="text-[11px] leading-snug text-app-secondary whitespace-pre-wrap break-words font-mono">
              {shown || 'No library matches that search.'}
            </pre>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
};
